module trash_game(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [207:0] deck,\n    output reg done,\n    output reg winner\n);\n\n    // State definitions\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] DEAL = 4'd1;\n    localparam [3:0] TURN_START = 4'd2;\n    localparam [3:0] DRAW = 4'd3;\n    localparam [3:0] CHECK = 4'd4;\n    localparam [3:0] NUMBER_STRATEGY = 4'd5;\n    localparam [3:0] JACK_STRATEGY = 4'd6;\n    localparam [3:0] FILL_SLOT = 4'd7;\n    localparam [3:0] UNCOVER = 4'd8;\n    localparam [3:0] DISCARD = 4'd9;\n    localparam [3:0] DONE_STATE = 4'd10;\n\n    // Card values\n    localparam [3:0] ACE = 4'd0;\n    localparam [3:0] JACK = 4'd10;\n    localparam [3:0] QUEEN = 4'd11;\n    localparam [3:0] KING = 4'd12;\n\n    // Internal registers\n    reg [3:0] fsm_state;\n    reg [3:0] current_card;\n    reg player_turn;\n    reg [9:0] theta_filled;\n    reg [9:0] friend_filled;\n    reg [39:0] theta_faceup;\n    reg [39:0] friend_faceup;\n    reg [1:0] seen_count [0:12];\n    reg [5:0] deck_ptr;\n    reg [3:0] temp_slot;\n    reg [3:0] best_slot_theta;\n    reg [3:0] lowest_unfilled_friend;\n    reg all_filled_theta;\n    reg all_filled_friend;\n    reg [3:0] deck_memory [0:51];\n\n    // Combinational: compute best slot for Theta\n    always @(*) begin\n        best_slot_theta = 4'd0;\n        reg [1:0] best_remaining = 2'd3;\n        integer i;\n        for (i = 0; i < 10; i = i + 1) begin\n            if (~theta_filled[i]) begin\n                reg [1:0] remaining = 2'd4 - seen_count[i];\n                if (remaining < best_remaining) begin\n                    best_remaining = remaining;\n                    best_slot_theta = i;\n                end\n            end\n        end\n    end\n\n    // Combinational: lowest unfilled slot for Friend\n    always @(*) begin\n        lowest_unfilled_friend = 4'd0;\n        integer i;\n        for (i = 0; i < 10; i = i + 1) begin\n            if (~friend_filled[i]) begin\n                lowest_unfilled_friend = i;\n                break;\n            end\n        end\n    end\n\n    // Combinational: check all filled\n    always @(*) begin\n        all_filled_theta = (theta_filled == 10'h3FF);\n        all_filled_friend = (friend_filled == 10'h3FF);\n    end\n\n    // State update\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            fsm_state <= IDLE;\n            done <= 1'b0;\n            winner <= 1'b0;\n            deck_ptr <= 6'd0;\n            current_card <= 4'd0;\n            player_turn <= 1'b0;\n            theta_filled <= 10'd0;\n            friend_filled <= 10'd0;\n            theta_faceup <= 40'd0;\n            friend_faceup <= 40'd0;\n            temp_slot <= 4'd0;\n            integer j;\n            for (j = 0; j < 13; j = j + 1) begin\n                seen_count[j] <= 2'd0;\n            end\n            for (j = 0; j < 52; j = j + 1) begin\n                deck_memory[j] <= deck[4*j +: 4];\n            end\n        end else begin\n            case (fsm_state)\n                IDLE: begin\n                    if (start) begin\n                        fsm_state <= DEAL;\n                    end\n                end\n                \n                DEAL: begin\n                    deck_ptr <= 6'd80;\n                    player_turn <= 1'b0;\n                    theta_filled <= 10'd0;\n                    friend_filled <= 10'd0;\n                    theta_faceup <= 40'd0;\n                    friend_faceup <= 40'd0;\n                    integer j;\n                    for (j = 0; j < 13; j = j + 1) begin\n                        seen_count[j] <= 2'd0;\n                    end\n                    fsm_state <= TURN_START;\n                end\n                \n                TURN_START: begin\n                    fsm_state <= DRAW;\n                end\n                \n                DRAW: begin\n                    current_card <= deck_memory[deck_ptr];\n                    deck_ptr <= deck_ptr + 6'd1;\n                    fsm_state <= CHECK;\n                end\n                \n                CHECK: begin\n                    if (current_card == JACK) begin\n                        fsm_state <= JACK_STRATEGY;\n                    end else if (current_card <= 9) begin\n                        fsm_state <= NUMBER_STRATEGY;\n                    end else begin\n                        fsm_state <= DISCARD;\n                    end\n                end\n                \n                NUMBER_STRATEGY: begin\n                    if (player_turn == 1'b0) begin\n                        if (~theta_filled[current_card]) begin\n                            temp_slot <= current_card;\n                            fsm_state <= FILL_SLOT;\n                        end else begin\n                            fsm_state <= DISCARD;\n                        end\n                    end else begin\n                        if (~friend_filled[current_card]) begin\n                            temp_slot <= current_card;\n                            fsm_state <= FILL_SLOT;\n                        end else begin\n                            fsm_state <= DISCARD;\n                        end\n                    end\n                end\n                \n                JACK_STRATEGY: begin\n                    if (player_turn == 1'b0) begin\n                        temp_slot <= best_slot_theta;\n                    end else begin\n                        temp_slot <= lowest_unfilled_friend;\n                    end\n                    fsm_state <= FILL_SLOT;\n                end\n                \n                FILL_SLOT: begin\n                    if (player_turn == 1'b0) begin\n                        theta_filled[temp_slot] <= 1'b1;\n                        theta_faceup[4*temp_slot +: 4] <= current_card;\n                        seen_count[current_card] <= seen_count[current_card] + 2'd1;\n                        if (all_filled_theta) begin\n                            done <= 1'b1;\n                            winner <= 1'b1;\n                            fsm_state <= DONE_STATE;\n                        end else begin\n                            fsm_state <= UNCOVER;\n                        end\n                    end else begin\n                        friend_filled[temp_slot] <= 1'b1;\n                        friend_faceup[4*temp_slot +: 4] <= current_card;\n                        seen_count[current_card] <= seen_count[current_card] + 2'd1;\n                        if (all_filled_friend) begin\n                            done <= 1'b1;\n                            winner <= 1'b0;\n                            fsm_state <= DONE_STATE;\n                        end else begin\n                            fsm_state <= UNCOVER;\n                        end\n                    end\n                end\n                \n                UNCOVER: begin\n                    if (player_turn == 1'b0) begin\n                        current_card <= deck_memory[temp_slot];\n                    end else begin\n                        current_card <= deck_memory[10 + temp_slot];\n                    end\n                    fsm_state <= CHECK;\n                end\n                \n                DISCARD: begin\n                    if (current_card <= 12) begin\n                        seen_count[current_card] <= seen_count[current_card] + 2'd1;\n                    end\n                    player_turn <= ~player_turn;\n                    fsm_state <= TURN_START;\n                end\n                \n                DONE_STATE: begin\n                    fsm_state <= DONE_STATE;\n                end\n                \n                default: begin\n                    fsm_state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule